public boolean validateWrite()
{
    boolean ret = next validateWrite();
    if (ret)
    {
        if ((TAMRebateDeal::find(this.RebateDeal).ModuleInventCustVend == ModuleInventCustVend::Cust) && TAMRebateDeal::find(this.RebateDeal).RebateReconciliation == TAMRebateReconciliation::Deal
            && this.METSkipPosting)
        {
            ret = checkFailed("@MET:ManualRebatePostingValidation");
        }
    }
    return ret;
}
